import{_ as t,o as s,c as e,a5 as d}from"./chunks/framework.CslsFoWx.js";const b=JSON.parse('{"title":"Kiosque self-service","description":"","frontmatter":{"pageClass":"wide","aside":false},"headers":[],"relativePath":"modules/09-kiosk.md","filePath":"generated/modules/09-kiosk.md","lastUpdated":null}'),n={name:"modules/09-kiosk.md"};function i(r,a,o,p,l,c){return s(),e("div",null,[...a[0]||(a[0]=[d('<h1 id="kiosque-self-service" tabindex="-1">Kiosque self-service <a class="header-anchor" href="#kiosque-self-service" aria-label="Permalink to &quot;Kiosque self-service&quot;">​</a></h1><p><span class="badge partial">Partiel</span> <span class="muted">Phase 4 · <a href="/VendoraSystem-docs/specs/09-kiosk">spécification complète</a></span></p><p>Borne de commande dans les deux apps (rôle d&#39;appareil KIOSK) : accueil brandé, sur place / à emporter, catalogue, modificateurs, panier, paiement au comptoir (encaissé à la caisse par numéro ou QR) ou au terminal (confirmation manuelle), numéro court, ticket, inactivité, langues ; supervision, désactivation à distance et statistiques de conversion au back-office ; permissions du rôle KIOSK.</p><div class="kpis"><div><b>18</b><span>faites</span></div><div><b>5</b><span>partielles</span></div><div><b>1</b><span>à faire</span></div><div><b>0</b><span>bloquées</span></div></div><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Presets kiosque du magasin</strong><br><span class="muted">L&#39;owner publie au back-office des presets versionnés : écran d&#39;accueil, mode de paiement, validation manuelle, étape sur place / à emporter, délai d&#39;inactivité, produits mis en avant.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-KIOSK-04, RG-KIOSK-05, RG-KIOSK-09, RG-THEME-14</td><td>2.25</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-reliquats-personnalisation">📷</a></td></tr><tr><td><strong>Preset assigné à chaque appareil</strong><br><span class="muted">La configuration par appareil porte <code>kioskPresetId</code> (422 si inconnu), diffusée par <code>DeviceConfigUpdated</code> et <code>KioskPresetUpdated</code> jusqu&#39;au miroir local.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-THEME-14</td><td>2.22, 2.25</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-reliquats-personnalisation">📷</a></td></tr><tr><td><strong>Bannières promotionnelles</strong><br><span class="muted">Le preset porte des bannières (titre, cible, période de validité) qui disparaissent d&#39;elles-mêmes à expiration.<br><i>Lot 4.4 : images téléversées et référencées par le preset ; affichage sur la borne (cache multi-assets) : reste.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-THEME-14</td><td>2.25, 4.1</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-reliquats-personnalisation">📷</a></td></tr><tr><td><strong>Multilingue</strong><br><span class="muted">Les langues fr / en / ar (avec RTL) sont résolues appareil &gt; magasin ; le kiosque doit offrir un sélecteur de langue sur tous ses écrans.<br><i>Lot 4.1 : écrans de la borne en fr / en / ar (groupe kiosk de CaisseStrings), sélecteur sur tous les écrans, RTL en arabe.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-KIOSK-13, RG-THEME-12</td><td>2.25, 4.1</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-reliquats-personnalisation">📷</a></td></tr></tbody></table><h2 id="offline" tabindex="-1">Offline <a class="header-anchor" href="#offline" aria-label="Permalink to &quot;Offline&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Filtrage du hub pour le rôle KIOSK</strong><br><span class="muted">Le hub local ne relaie au kiosque que le catalogue et sa configuration, rattrapage compris.<br><i>Couvert par les tests du hub (<code>HubRouting</code>), sans appareil kiosque réel.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-KIOSK-10</td><td>2.26</td><td></td></tr><tr><td><strong>Commandes kiosque sans internet</strong><br><span class="muted">Sans internet, le kiosque continue en paiement au comptoir via le hub local ; sans hub ni imprimante, il passe en « Borne momentanément indisponible ».<br><i>Lot 4.1 : la borne commande hors ligne via le journal local et le hub (PAY_AT_COUNTER) ; sans hub ni imprimante, indisponibilité non automatisée (reste).</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-KIOSK-10</td><td>4.1</td><td></td></tr></tbody></table><h2 id="mode-verrouille-securite" tabindex="-1">Mode verrouillé &amp; sécurité <a class="header-anchor" href="#mode-verrouille-securite" aria-label="Permalink to &quot;Mode verrouillé &amp; sécurité&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Mode kiosque verrouillé</strong><br><span class="muted">L&#39;app tourne épinglée (Lock Task Mode Android, Guided Access / Single App Mode iPad) et ne se quitte qu&#39;avec un code de déverrouillage.<br><i>Lot 4.1 : Lock Task Mode à l&#39;entrée de la borne sur Android (épinglage demandé hors device owner), accès guidé recommandé et détecté sur iPad ; sortie par 5 taps + PIN manager vers l&#39;écran technique.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-KIOSK-01</td><td>4.1</td><td></td></tr><tr><td><strong>Permissions restreintes du rôle KIOSK</strong><br><span class="muted">Un jeton KIOSK crée des commandes et imprime, mais remise, retour, tiroir ou rapports répondent 403 FORBIDDEN_FOR_DEVICE_ROLE (tentative tracée).<br><i>Lot 4.1 : jeton KIOSK limité à la synchronisation, aux assets et au heartbeat (403 FORBIDDEN_FOR_DEVICE_ROLE) ; au push, seuls les faits du parcours client sont acceptés, le reste est rejeté avec ce code.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td>RG-KIOSK-02</td><td>4.1</td><td></td></tr></tbody></table><h2 id="parcours-client" tabindex="-1">Parcours client <a class="header-anchor" href="#parcours-client" aria-label="Permalink to &quot;Parcours client&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Accueil brandé</strong><br><span class="muted">Écran d&#39;accueil au thème du magasin (logo, couleurs, titre du preset), tap pour commencer, langue par défaut configurée.<br><i>Lot 4.1 : accueil plein écran aux couleurs du magasin, logo ou nom, titre et sous-titre du preset, « Touchez pour commander », sélecteur de langue.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-KIOSK-13</td><td>2.25, 4.1</td><td></td></tr><tr><td><strong>Choix sur place / à emporter</strong><br><span class="muted">Étape obligatoire pour un restaurant, pouvant changer la TVA ; masquée pour les autres profils.<br><i>Lot 4.1 : étape affichée pour un magasin RESTAURANT si le preset la demande ; portée par la commande (DINE_IN / TAKEAWAY) et les statistiques.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-KIOSK-04</td><td>4.1</td><td></td></tr><tr><td><strong>Catalogue filtré pour le kiosque</strong><br><span class="muted">Seuls les produits <code>availableOnKiosk</code> et non en rupture sont affichés, prix TTC non modifiables, catégories mises en avant.<br><i>Lot 4.1 : catégories + grille des produits actifs et disponibles dans le magasin, produits mis en avant du preset en tête, prix TTC, produits au poids exclus, variantes choisies.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-KIOSK-12</td><td>4.1</td><td></td></tr><tr><td><strong>Fiche produit avec modificateurs</strong><br><span class="muted">Le client personnalise son plat ; un choix obligatoire manquant bloque l&#39;ajout au panier.<br><i>Lot 4.1 : fiche avec modificateurs (groupes obligatoires bloquants, règles partagées), quantité, ajout au panier.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-KIOSK-03, RG-REST-08</td><td>2.3, 4.1</td><td></td></tr><tr><td><strong>Panier et délai d&#39;inactivité</strong><br><span class="muted">Avertissement « Êtes-vous toujours là ? » puis retour à l&#39;accueil et purge du panier, sans aucun événement de vente ; compteur d&#39;abandon local.<br><i>Lot 4.1 : panier local à la session ; inactivité du preset avec compte à rebours à T-15 s, retour à l&#39;accueil, panier purgé, abandon compté par étape (KioskSession partagé).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-KIOSK-09</td><td>4.1</td><td></td></tr><tr><td><strong>Accessibilité</strong><br><span class="muted">Cibles ≥ 48 dp, contraste WCAG AA, grande police, interface compactée en bas d&#39;écran.<br><i>Lot 4.1 : cibles ≥ 48 dp / pt, gros textes, contrastes des tokens ; mode « interface compactée en bas » non fait.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-KIOSK-13</td><td>4.1</td><td></td></tr></tbody></table><h2 id="paiement-commande" tabindex="-1">Paiement &amp; commande <a class="header-anchor" href="#paiement-commande" aria-label="Permalink to &quot;Paiement &amp; commande&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Paiement au comptoir</strong><br><span class="muted">La commande est créée « à payer », un ticket avec numéro et QR s&#39;imprime ; la caisse la retrouve par numéro ou QR et l&#39;encaisse en deux gestes.<br><i>Lot 4.1 : commande envoyée en cuisine puis « à régler en caisse », ticket avec numéro et QR ; la caisse la retrouve par numéro ou scan et l&#39;encaisse comme une addition.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-KIOSK-05</td><td>4.1</td><td></td></tr><tr><td><strong>Paiement au terminal et validation manuelle</strong><br><span class="muted">« Payez sur le terminal » avec confirmation manuelle tracée ou par webhook, rapprochement quotidien des validations manuelles avec le TPE.<br><i>Lot 4.1 : écran « Payez sur le terminal » ; confirmation manuelle (si autorisée par le preset) → OrderPaymentConfirmed, commande PAID et en cuisine ; confirmations conservées pour le rapprochement. Webhook TPE natif : reste.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-KIOSK-05, RG-KIOSK-07</td><td>2.10, 2.16, 4.1</td><td></td></tr><tr><td><strong>Envoi en cuisine à la commande ou au paiement</strong><br><span class="muted">Selon le magasin, la commande part en cuisine dès sa confirmation ou une fois payée.<br><i>Lot 4.1 : FIRE_ON_ORDER pour le comptoir, FIRE_ON_PAYMENT pour le terminal (envoi au moment de la confirmation).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-KIOSK-06</td><td>4.1</td><td></td></tr><tr><td><strong>Numéros de retrait courts</strong><br><span class="muted">Numéro du jour (K-042) alloué séquentiellement par le hub local, préfixé par appareil sans hub (K1-042).<br><i>Lot 4.1 : numéro court du jour « K3F-042 » (préfixe par appareil + compteur local) affiché, imprimé et dans le QR ; allocation séquentielle par le hub : reste.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-KIOSK-08, RG-SYNC-25</td><td>2.6, 4.1</td><td></td></tr><tr><td><strong>Commandes kiosque en cuisine</strong><br><span class="muted">La commande kiosque suit le même routage et les mêmes états qu&#39;une commande de salle, badgée KIOSQUE avec son numéro.<br><i>Lot 4.1 : même flux OrderLinesSent que la salle ; badge Kiosque + numéro sur le KDS.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-KIOSK-03, RG-REST-24</td><td>4.1</td><td></td></tr><tr><td><strong>Ticket kiosque et imprimante en panne</strong><br><span class="muted">Ticket au gros numéro de commande ; si l&#39;impression échoue, numéro affiché en grand ≥ 10 s et commande envoyée quand même.<br><i>Lot 4.1 : ticket kiosque (numéro en double taille, sur place / à emporter, lignes, total, « à régler en caisse » + QR ou « payé sur le terminal ») ; imprimante en panne → numéro en plein écran et bouton « J&#39;ai noté mon numéro ».</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-KIOSK-11</td><td>4.1</td><td></td></tr></tbody></table><h2 id="supervision" tabindex="-1">Supervision <a class="header-anchor" href="#supervision" aria-label="Permalink to &quot;Supervision&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Supervision et heartbeat</strong><br><span class="muted">Chaque kiosque signale son état toutes les 60 s ; le back-office le marque « hors ligne » après 5 min sans signal.<br><i>Lot 4.1 : heartbeat toutes les 60 s (état, imprimante, verrouillage, dernière commande) ; page Bornes : en ligne ≤ 5 min, hors ligne, indisponible, désactivée.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-KIOSK-15</td><td>4.1</td><td></td></tr><tr><td><strong>Désactivation à distance</strong><br><span class="muted">La gérante désactive un kiosque : la commande en cours se termine puis l&#39;écran d&#39;indisponibilité s&#39;affiche, via le cloud et le hub.<br><i>Lot 4.1 : Désactiver / Réactiver au back-office → DeviceConfigUpdated (kioskDisabled) par le cloud et le hub ; la borne termine la commande en cours puis affiche l&#39;indisponibilité ; audit.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-KIOSK-14</td><td>4.1</td><td></td></tr><tr><td><strong>Statistiques de conversion</strong><br><span class="muted">Sessions, commandes, abandons par étape, panier moyen, répartition sur place / à emporter par kiosque.<br><i>Lot 4.1 : sessions, commandes, taux de conversion, abandons par étape, panier moyen, sur place / à emporter, par borne ; validations manuelles TPE à rapprocher.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-KIOSK-09, RG-KIOSK-15</td><td>4.1</td><td></td></tr></tbody></table><h2 id="variante-v2" tabindex="-1">Variante v2 <a class="header-anchor" href="#variante-v2" aria-label="Permalink to &quot;Variante v2&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Scan des articles par le client</strong><br><span class="muted">Variante retail : le client scanne ses articles à la caméra, les articles restreints passent au comptoir.<br><i>Hors périmètre v1 (variante v2 du kiosque).</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td>RG-KIOSK-16</td><td></td><td></td></tr></tbody></table><h2 id="reste-a-faire" tabindex="-1">Reste à faire <a class="header-anchor" href="#reste-a-faire" aria-label="Permalink to &quot;Reste à faire&quot;">​</a></h2><ul><li>Numéros courts séquentiels alloués par le hub local (aujourd&#39;hui préfixe par appareil + compteur local).</li><li>Webhook TPE natif, expiration des commandes TPE non confirmées, rapprochement automatique avec le TPE, sortie de stock à l&#39;encaissement TPE (pas de Sale).</li><li>Affichage des bannières et de l&#39;image d&#39;accueil (cache multi-assets), mode accessibilité « interface en bas », indisponibilité automatique sans hub ni imprimante.</li><li>Pourboire depuis le kiosque ; scan client (variante v2).</li></ul>',20)])])}const g=t(n,[["render",i]]);export{b as __pageData,g as default};
